rows=[];t=3.0
for i,(line,vis) in enumerate(B,1):
    words=len(line.split())
    d=max(2.0,min(3.0,round(words*0.4+0.9,1)))
    rows.append((i,f"{int(t//60)}:{t%60:04.1f}",d,line,f"{vis}. {STYLE}"))
    t+=d
with open("visual_prompts.csv","w",newline="",encoding="utf-8") as f:
    w=csv.writer(f);w.writerow(["#","start_time_approx","duration_s","narration","prompt"]);w.writerows(rows)
with open("visual_prompts.md","w",encoding="utf-8") as f:
    f.write("# Hand-drawn visual prompts — The Psychology of People Who Want to Do Everything\n\n")
    f.write("Timing is an estimate from word count (about 2–3 s per image). Re-time once the real voice-over exists.\n\n")
    f.write("## Style block (already appended to every prompt; reuse for any extra image)\n\n"+STYLE+"\n\n")
    f.write("**Tips:** keep the same seed / reference image of your stickman in every generation, same aspect ratio 16:9, and do not ask for colour except the one amber accent.\n\n")
    for i,ts,d,line,p in rows:
        f.write(f"### {i}. {ts} ({d}s)\n*\"{line}\"*\n\n{p}\n\n")
print(len(rows),"prompts, ends about",f"{int(t//60)}:{t%60:04.1f}")
